    return -2;
  }

  *chunk = schunk->data[nchunk];
  if (*chunk == 0) {
    *needs_free = 0;
    return 0;
  }

  *needs_free = false;
  return sw32_(*chunk + BLOSC2_CHUNK_CBYTES);
}
